#if UNITY_EDITOR || DEVELOPMENT_BUILD
using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using Unity.Netcode;
using Unity.Netcode.Components;
using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.UI;
namespace WhatTheFish {
 public sealed class FootballAudioReview:MonoBehaviour {
  string folder,shared;bool failed;AppRoot app;FootballBall ball;FootballMatch match;FootballAudio audio;Athlete actor;int duplicates;readonly HashSet<uint> ids=new();readonly Dictionary<FootballSound,int> counts=new();
  [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Init(){var a=Environment.GetCommandLineArgs();int i=Array.IndexOf(a,"-footballAudioReview");if(i>=0&&i+1<a.Length)new GameObject("Football audio verification").AddComponent<FootballAudioReview>().folder=a[i+1];}
  void Check(bool ok,string text){failed|=!ok;File.AppendAllText(Path.Combine(folder,"results.txt"),(ok?"PASS ":"FAIL ")+text+"\n");}
  int Count(FootballSound c)=>counts.TryGetValue(c,out int n)?n:0;
  void Heard(FootballSound c,Vector3 p,float gain,string source,uint id){counts[c]=Count(c)+1;if(source=="network"&&!ids.Add(id))duplicates++;File.AppendAllText(Path.Combine(folder,"events.tsv"),$"{FootballMotion.Clock:F4}\t{c}\t{source}\t{id}\t{gain:F3}\t{p}\n");}
  Vector3 Point(float x,float z,float y=0)=>ball.Pitch.TransformPoint(new Vector3(ball.PitchBounds.center.x+x,ball.PitchBounds.max.y+y,ball.PitchBounds.center.z+z));
  void Place(Athlete a,float x,float z){a.capsule.enabled=false;var p=Point(x,z,.02f);a.transform.SetPositionAndRotation(p,ball.Pitch.rotation);var n=a.GetComponent<NetworkTransform>();if(n&&n.IsSpawned)n.Teleport(p,a.transform.rotation,Vector3.one);a.capsule.enabled=ball.HasAuthority;a.ResetLocomotion();Physics.SyncTransforms();}
  void Free(float x=7,float z=6,float y=.3f,Vector3 velocity=default){ball.ReviewFootballBall(Point(x,z,y),ball.Pitch.TransformDirection(velocity));Physics.SyncTransforms();}
  IEnumerator Acquire(){Place(actor,0,-8);Free();yield return new WaitForSeconds(.25f);ball.ReviewFootballBall(ball.FootPosition(actor),Vector3.zero);ball.RefreshControl(actor);yield return new WaitForSeconds(.1f);Check(ball.CurrentController==actor,"ball received at feet");}
  bool Use(SportsProp kind){ball.ReviewGiveFootballProp(actor,kind);return ball.TryUseProp(actor,ball.PropSlot(actor).revision,match.Snapshot.revision,actor.transform.eulerAngles.y);}
  IEnumerator Start(){
   Directory.CreateDirectory(folder);shared=Directory.GetParent(folder).FullName;File.WriteAllText(Path.Combine(folder,"results.txt"),"");FootballAudio.Trace+=Heard;
   float timeout=Time.realtimeSinceStartup+90;while((!(app=AppRoot.Instance)||!app.Exploring||!FootballBall.Instance)&&Time.realtimeSinceStartup<timeout)yield return null;
   ball=FootballBall.Instance;actor=app?app.LocalAthlete:null;match=FootballMatch.Instance;audio=FootballAudio.Instance;
   if(!ball||!actor||!audio){Check(false,"football audio initialized");Finish();yield break;}
   DevelopmentProbe.Driving=false;DevelopmentProbe.TurnCommandActive=true;DevelopmentProbe.TurnCommand=default;app.view.mode=2;yield return new WaitForSeconds(.6f);
   Check(audio.LoadedClips==80,"80 approved clips loaded with shared references: "+audio.LoadedClips);Check(FindObjectsByType<AudioListener>(FindObjectsSortMode.None).Count(x=>x.enabled)==1,"one enabled listener");
   Check(audio.ReviewClip(FootballSound.Pickup)==Resources.Load<AudioClip>("BasketballAudio/pickup-01"),"pickup references the original shared asset");
   var soft=audio.ReviewClip(FootballSound.WallPreview);var samples=new float[soft.samples];soft.GetData(samples,0);Check(samples.Max(x=>Mathf.Abs(x))<.16f,"import preserves soft Wall preview level");
   if(!ball.HasAuthority){
    timeout=Time.realtimeSinceStartup+150;while(!File.Exists(Path.Combine(shared,"host-done"))&&Time.realtimeSinceStartup<timeout)yield return null;yield return new WaitForSeconds(.5f);
    Check(File.Exists(Path.Combine(shared,"host-done")),"host gameplay completed");foreach(var cue in new[]{FootballSound.KickLight,FootballSound.KickShot,FootballSound.Bounce,FootballSound.Post,FootballSound.Net,FootballSound.Pickup,FootballSound.TurboStart,FootballSound.PortalOpen,FootballSound.WallPlace,FootballSound.WallHit})Check(Count(cue)>0,"guest heard "+cue);
    Check(ids.Count>10&&duplicates==0,"live event IDs received without duplicates: "+ids.Count);Check(FootballAudio.NetworkDropped==0,"no stale live events dropped");Finish();yield break;
   }
   var peers=Athlete.Active.Where(a=>a.GetComponent<NetworkObject>()&&a.GetComponent<NetworkObject>().IsSpawned).OrderBy(a=>a.GetComponent<NetworkObject>().OwnerClientId).ToArray();
   if(peers.Length==0){Free(3,3,1.5f);yield return new WaitForSeconds(1);Check(Count(FootballSound.Bounce)>0,"Explore physical bounce");Check(Count(FootballSound.Score)==0&&Count(FootballSound.Kickoff)==0&&Count(FootballSound.Final)==0,"Explore has no score or match whistles");}
   Check(peers.Length==0?match.StartTestMatch():match.StartMatch(),"formal match starts");var roster=peers.Length==0?new[]{actor}:peers;for(int i=0;i<roster.Length;i++)Check(match.ChooseTeam(roster[i],i%2==0?FootballTeam.A:FootballTeam.B,match.Snapshot.revision),"team choice "+i);
   match.Selection.Complete(new System.Random(7));match.State.TeamsConfirmed(match.Now);yield return new WaitForSeconds(3.3f);Check(match.Running&&Count(FootballSound.Kickoff)==1,"one whistle at actual kickoff release");
   for(int i=1;i<roster.Length;i++)Place(roster[i],10,8+i);
   yield return Acquire();int dribbles=Count(FootballSound.Dribble);yield return new WaitForSeconds(.7f);Check(Count(FootballSound.Dribble)==dribbles,"stationary held football is silent");
   int movingTouches=Count(FootballSound.Dribble);DevelopmentProbe.TurnCommand=new PlayerCommand{move=Vector2.up,heading=ball.Pitch.eulerAngles.y};yield return new WaitForSeconds(1.2f);DevelopmentProbe.TurnCommand=default;Check(Count(FootballSound.Dribble)>movingTouches,"moving dribble follows visible foot contacts");
   int kicks=Count(FootballSound.KickLight);Check(ball.TryKick(actor,.1f),"light kick accepted");Check(Count(FootballSound.KickLight)==kicks+1,"one light kick at release");Check(!ball.TryKick(actor,float.NaN)&&Count(FootballSound.KickLight)==kicks+1,"invalid kick produces no sound");yield return new WaitForSeconds(.25f);
   yield return Acquire();int shots=Count(FootballSound.KickShot);Check(ball.TryKick(actor,1),"power kick accepted");Check(Count(FootballSound.KickShot)==shots+1,"one power kick at release");
   Free();Place(actor,0,-8);yield return new WaitForSeconds(.2f);int steps=Count(FootballSound.Walk)+Count(FootballSound.Run);DevelopmentProbe.TurnCommand=new PlayerCommand{move=Vector2.up,heading=ball.Pitch.eulerAngles.y};yield return new WaitForSeconds(1.4f);DevelopmentProbe.TurnCommand=default;yield return new WaitForSeconds(.3f);Check(Count(FootballSound.Walk)+Count(FootballSound.Run)>steps+2,"moving gait produces planted steps");
   int lands=Count(FootballSound.Land);actor.RequestJump();yield return new WaitForSeconds(1.8f);Check(Count(FootballSound.Land)==lands+1,"one jump landing");
   Place(actor,0,-8);Free();yield return new WaitForSeconds(.2f);int slides=Count(FootballSound.Slide);Check(actor.TryTackle(),"tackle accepted");yield return new WaitForSeconds(.6f);Check(Count(FootballSound.Slide)==slides+1,"slide starts once");yield return new WaitForSeconds(1);
   int bounces=Count(FootballSound.Bounce);Free(5,5,1.4f,Vector3.down);yield return new WaitForSeconds(.8f);Check(Count(FootballSound.Bounce)>bounces,"physical turf impact");
   var post=ball.Pitch.GetComponentsInChildren<Collider>().First(c=>c.name=="Collision_Post");int posts=Count(FootballSound.Post);var toward=(post.bounds.center-ball.KickoffPosition).normalized;toward.y=0;toward.Normalize();ball.ReviewFootballBall(post.bounds.center-toward*.6f,toward*7);yield return new WaitForSeconds(.3f);Check(Count(FootballSound.Post)>posts,"goal post contact through physical/containment resolution");
   var net=ball.Pitch.GetComponentsInChildren<FootballGoalNet>().First();int nets=Count(FootballSound.Net);var bounds=ball.GoalBounds(0);var inside=ball.Pitch.TransformPoint(new Vector3(bounds.center.x,bounds.min.y+.7f,bounds.center.z));ball.ReviewFootballBall(inside,ball.Pitch.forward*ball.GoalSign(0)*7);yield return new WaitForSeconds(.6f);Check(Count(FootballSound.Net)>nets,"actual goal-net contact");
   Free();Place(actor,0,-8);yield return new WaitForSeconds(.2f);int falls=Count(FootballSound.Fall);actor.GetComponent<FootballTackle>().ReceiveHit(ball.Pitch.forward);yield return new WaitForSeconds(.85f);Check(Count(FootballSound.Body)>0&&Count(FootballSound.Fall)==falls+1,"accepted tackle hit then grounded fall");
   int goals=Count(FootballSound.Score);var goal=ball.GoalBounds(0);var start=ball.Pitch.TransformPoint(new Vector3(goal.center.x,goal.min.y+.5f,ball.GoalFront(0)-ball.GoalSign(0)*1.5f));ball.ReviewFootballBall(start,ball.Pitch.forward*ball.GoalSign(0)*10);match.ResetAbilityGoalTracking();yield return new WaitForSeconds(.5f);Check(Count(FootballSound.Score)==goals+1,"actual whole-ball crossing confirms goal once");yield return new WaitForSeconds(3.5f);
   Place(actor,0,-8);Free();ball.ResetFootballProps();yield return new WaitForSeconds(5.3f);Check(Count(FootballSound.Spawn)>0,"prop materialization cue");var pickup=ball.PropAnchor(ball.Props.pickup.anchor);int pickups=Count(FootballSound.Pickup);var local=ball.Pitch.InverseTransformPoint(pickup)-ball.PitchBounds.center;Place(actor,local.x,local.z);yield return new WaitForSeconds(.2f);Check(Count(FootballSound.Pickup)==pickups+1,"physical prop collection sounds once");
   Place(actor,0,-8);Free();yield return new WaitForSeconds(.3f);Check(Use(SportsProp.Turbo),"Turbo accepted");yield return new WaitForSeconds(.2f);float sfx=MenuPreferences.SFXVolume;MenuPreferences.SetSFX(0);yield return null;yield return null;Check(audio.ReviewTurboVolume==0,"SFX mute applies to current Turbo loop");MenuPreferences.SetSFX(sfx);yield return new WaitForSeconds(5.2f);Check(Count(FootballSound.TurboEnd)>0,"Turbo expiry cue");
   Check(Use(SportsProp.Portal),"Portal accepted");yield return new WaitForSeconds(1);Check(ball.CurrentController==actor&&Count(FootballSound.PortalIn)>0&&Count(FootballSound.PortalOut)>0&&Count(FootballSound.PortalClose)>0,"Portal shrink, grow, receive and close follow phases");
   Free();Place(actor,0,-8);yield return new WaitForSeconds(.25f);ball.ReviewGiveFootballProp(actor,SportsProp.Wall);app.view.yaw=actor.transform.eulerAngles.y;FootballPropHUD.Instance.Activate();yield return null;Check(Count(FootballSound.WallPreview)==1,"Wall preview before consumption");FootballPropHUD.Instance.Activate();yield return new WaitForSeconds(.2f);Check(Count(FootballSound.WallPlace)==1&&ball.Props.wallA.active,"accepted Wall placement");
   var wall=ball.Props.wallA;int walls=Count(FootballSound.WallHit);ball.ReviewFootballBall(wall.Centre-wall.Rotation*Vector3.forward*1.5f,wall.Rotation*Vector3.forward*15);yield return new WaitForSeconds(.2f);Check(Count(FootballSound.WallHit)==walls+1,"physics and sweep share one Wall impact");ball.ReviewExpireFootballEffects();yield return new WaitForSeconds(.2f);Check(Count(FootballSound.WallExpire)==1,"one Wall expiry");
   int opens=Count(FootballSound.UIOpen);var settings=FootballHUD.Instance.GetComponentsInChildren<Button>(true).First(b=>b.name=="Pitch settings");settings.onClick.Invoke();yield return null;Check(Count(FootballSound.UIOpen)==opens+1,"one settings click");FootballHUD.Instance.SelectMenu(2);yield return new WaitForEndOfFrame();CaptureSettings();Check(FootballHUD.Instance.GetComponentsInChildren<Slider>(true).Length==4,"four shared volume controls");FootballHUD.Instance.CloseMenu();
   yield return Acquire();var kick=FootballHUD.Instance.Kick;yield return null;int taps=Count(FootballSound.UIClick);var pointer=new PointerEventData(EventSystem.current){pointerId=807,button=PointerEventData.InputButton.Left};ExecuteEvents.Execute(kick.gameObject,pointer,ExecuteEvents.pointerDownHandler);ExecuteEvents.Execute(kick.gameObject,pointer,ExecuteEvents.pointerDownHandler);yield return null;kick.CancelGesture();ExecuteEvents.Execute(kick.gameObject,pointer,ExecuteEvents.pointerUpHandler);Check(Count(FootballSound.UIClick)==taps+1,"held button clicks once for duplicate down");
   // Exercise rules-driven transitions without waiting three real minutes.
   Free();int finalBeforeOvertime=Count(FootballSound.Final);match.State.Start(match.Now-2,.1,2,0);match.State.Advance(match.Now-1);yield return new WaitForSeconds(.15f);int final=Count(FootballSound.Final);Check(match.Snapshot.phase==FootballMatchPhase.Overtime&&Count(FootballSound.Overtime)>0,"tied regulation enters audible golden goal");Check(Count(FootballSound.Final)==finalBeforeOvertime,"overtime does not stop play with a final whistle");yield return new WaitForSeconds(2.4f);Check(Count(FootballSound.Final)==final+1&&Count(FootballSound.Draw)>0,"final whistle then draw result");
   Free();match.State.Start(match.Now,2,3,0);match.State.Advance(match.Now);yield return null;match.State.Goal(FootballTeam.A,match.Now);yield return null;match.State.ResetCompleted(match.Now);match.State.Advance(match.Now);yield return new WaitForSeconds(3.5f);Check(Count(FootballSound.Win)>0,"local winner receives win result");
   match.State.Start(match.Now,2,3,0);match.State.Advance(match.Now);yield return null;match.State.Goal(FootballTeam.B,match.Now);yield return null;match.State.ResetCompleted(match.Now);match.State.Advance(match.Now);yield return new WaitForSeconds(3.5f);Check(Count(FootballSound.Loss)>0,"local loser receives loss result");
   Check(ids.Count==0,"host does not replay its own RPCs");audio.SendMessage("OnApplicationPause",true);Check(audio.PlayingVoices==0&&!audio.ReviewLoopsPlaying,"suspend stops voices and loops");audio.SendMessage("OnApplicationPause",false);yield return null;
   File.WriteAllText(Path.Combine(shared,"host-done"),"ready");yield return new WaitForSeconds(.8f);Finish();
  }
  void SaveCamera(Camera camera,string name,int width,int height){var rt=RenderTexture.GetTemporary(width,height,24);var previous=RenderTexture.active;var target=camera.targetTexture;camera.targetTexture=rt;camera.Render();RenderTexture.active=rt;var image=new Texture2D(width,height,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,width,height),0,0);image.Apply();File.WriteAllBytes(Path.Combine(folder,name+".png"),image.EncodeToPNG());Destroy(image);camera.targetTexture=target;RenderTexture.active=previous;RenderTexture.ReleaseTemporary(rt);}
  void CaptureSettings(){if(SystemInfo.graphicsDeviceType==UnityEngine.Rendering.GraphicsDeviceType.Null)return;var c=FootballHUD.Instance.GetComponentInParent<Canvas>();var mode=c.renderMode;var camera=c.worldCamera;float distance=c.planeDistance;c.renderMode=RenderMode.ScreenSpaceCamera;c.worldCamera=Camera.main;c.planeDistance=1;Canvas.ForceUpdateCanvases();SaveCamera(Camera.main,"sound-settings",Screen.width,Screen.height);c.renderMode=mode;c.worldCamera=camera;c.planeDistance=distance;Canvas.ForceUpdateCanvases();}
  void Finish(){FootballAudio.Trace-=Heard;MenuPreferences.Save();DevelopmentProbe.TurnCommandActive=false;DevelopmentProbe.TurnCommand=default;File.AppendAllText(Path.Combine(folder,"results.txt"),"FOOTBALL_AUDIO_COMPLETE success="+!failed+"\n");Application.Quit(failed?1:0);}
 }
}
#endif
